async function api(path,options={}){const c=options.controller||new AbortController(),timer=setTimeout(()=>c.abort(),options.timeout||180000);state.abort=c;try{const headers={...options.headers};let body=options.body;if(body&&!(body instanceof FormData)&&typeof body!=="string"){headers["Content-Type"]="application/json";body=JSON.stringify(body);}const r=await fetch(path,{...options,headers,body,signal:c.signal}),raw=await r.text();let data;try{data=raw?JSON.parse(raw):{};}catch{data={detail:raw.slice(0,400)};}if(!r.ok)throw new Error(typeof data.detail==="string"?data.detail:JSON.stringify(data.detail||data.error||("请求失败 "+r.status)));return data;}catch(err){if(err.name==="AbortError")throw new Error("本轮请求已中断（或等待超时）。生成任务可能仍在后台运行，请检查进度。");throw err;}finally{clearTimeout(timer);}}
function safeURL(raw){if(!raw)return null;try{const u=new URL(raw,location.href);if(["http:","https:","blob:"].includes(u.protocol)&&u.origin===location.origin)return u.href;}catch{}return null;}
