  if(!Number.isInteger(rate)||rate<8000||rate>96000||!raw.length||raw.length%2)throw new Error("收到无效的 PCM 音频片段。");
  const bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);
