function addTurn(role,text,options={}){const history=$("chat-history");history.querySelector(".chat-empty")?.remove();const row=node("article","turn "+role),bubble=node("div","turn-bubble"+(options.uncertain?" uncertain":""),text);row.append(node("div","turn-label",role==="user"?"你":"纸书智伴"),bubble);const url=imageURL(options.image);if(url){const img=node("img","turn-image");img.src=url;img.alt="本轮提问对应的视频画面";bubble.append(img);}if(options.evidence?.length){const tools=node("div","turn-tools");for(const e of options.evidence.slice(0,4)){const b=node("button","","第 "+(e.page_number||"—")+" 页 · "+fmt(e.start));b.type="button";b.onclick=()=>{if(finite(e.start))seek(e.start);if(e.page_number)showPage(e.page_number);evidence(options.evidence);tab("evidence");};tools.append(b);}row.append(tools);}if(options.meta)row.append(node("div","turn-meta",options.meta));history.append(row);history.scrollTop=history.scrollHeight;return row;}
